UPDATE `user` SET `real_name` = `nickname` WHERE `real_name` IS NULL OR `real_name` = '';

START TRANSACTION;
UPDATE `order` o JOIN `scenic_ticket` t ON t.scenic_id=o.scenic_id AND t.name=o.ticket_type
SET o.ticket_id=t.id,o.unit_price=CASE WHEN o.quantity>0 THEN ROUND(o.total_price/o.quantity,2) ELSE t.price END
WHERE o.ticket_id IS NULL;
SELECT c.id,a.id,a.nickname,c.reply,c.create_time FROM `comment` c
JOIN `admin` a ON a.id=(SELECT MIN(id) FROM `admin`)
WHERE c.reply IS NOT NULL AND c.reply<>'' AND NOT EXISTS(SELECT 1 FROM `comment_reply` r WHERE r.comment_id=c.id);
SELECT featured.comment_id,featured.image_url,0 FROM (
  SELECT MIN(c.id) AS comment_id,s.image AS image_url FROM `comment` c
  JOIN `scenic` s ON s.id=c.scenic_id
  WHERE c.status=1 AND s.image IS NOT NULL AND s.image<>''
  GROUP BY c.scenic_id,s.image
) featured
WHERE NOT EXISTS(SELECT 1 FROM `comment_image` ci WHERE ci.comment_id=featured.comment_id AND ci.image_url=featured.image_url);
SELECT first_reply.comment_id,a.id,a.nickname,'补充说明：如需进一步帮助，可以继续在评价区留言，我们会持续跟进。',DATE_ADD(first_reply.first_time,INTERVAL 1 DAY)
FROM (
  SELECT MIN(r.comment_id) AS comment_id,MIN(r.create_time) AS first_time FROM `comment_reply` r
  JOIN `comment` c ON c.id=r.comment_id GROUP BY c.scenic_id
) first_reply
JOIN `admin` a ON a.id=(SELECT MIN(id) FROM `admin`)
WHERE NOT EXISTS(SELECT 1 FROM `comment_reply` r2 WHERE r2.comment_id=first_reply.comment_id AND r2.content='补充说明：如需进一步帮助，可以继续在评价区留言，我们会持续跟进。');
COMMIT;
