INSERT INTO `order` (order_no,user_id,scenic_id,scenic_name,visit_date,ticket_type,quantity,total_price,contact_name,contact_phone,status,create_time,update_time) SELECT 'DEMO_V2_REVIEW_01_0',u.id,s.id,s.name,DATE_ADD(DATE_ADD(DATE_ADD(@demo_start, INTERVAL 1 MONTH), INTERVAL 3 DAY), INTERVAL 2 DAY),'成人票',2,s.price*2,u.nickname,u.phone,'COMPLETED',DATE_ADD(DATE_ADD(@demo_start, INTERVAL 1 MONTH), INTERVAL 3 DAY),TIMESTAMP(DATE_ADD(DATE_ADD(DATE_ADD(@demo_start, INTERVAL 1 MONTH), INTERVAL 3 DAY), INTERVAL 2 DAY)) FROM user u JOIN scenic s ON s.id=@scenic_1 WHERE u.id=@user_8 AND NOT EXISTS(SELECT 1 FROM `order` WHERE order_no='DEMO_V2_REVIEW_01_0');
INSERT INTO comment (user_id,scenic_id,score,content,reply,status,create_time) SELECT o.user_id,o.scenic_id,2,'【演示评价】杭州西湖的湖面倒影让人印象深刻。人多时体验一般，休息区域比较紧张，建议错峰安排。','【演示回复】感谢反馈，我们会持续完善路线提示与服务。',1,DATE_ADD(o.visit_date,INTERVAL 1 DAY) FROM `order` o WHERE o.order_no='DEMO_V2_REVIEW_01_0' AND NOT EXISTS(SELECT 1 FROM comment c WHERE c.user_id=o.user_id AND c.scenic_id=o.scenic_id);
INSERT INTO `order` (order_no,user_id,scenic_id,scenic_name,visit_date,ticket_type,quantity,total_price,contact_name,contact_phone,status,create_time,update_time) SELECT 'DEMO_V2_REVIEW_01_1',u.id,s.id,s.name,DATE_ADD(DATE_ADD(DATE_ADD(@demo_start, INTERVAL 2 MONTH), INTERVAL 4 DAY), INTERVAL 2 DAY),'成人票',3,s.price*3,u.nickname,u.phone,'COMPLETED',DATE_ADD(DATE_ADD(@demo_start, INTERVAL 2 MONTH), INTERVAL 4 DAY),TIMESTAMP(DATE_ADD(DATE_ADD(DATE_ADD(@demo_start, INTERVAL 2 MONTH), INTERVAL 4 DAY), INTERVAL 2 DAY)) FROM user u JOIN scenic s ON s.id=@scenic_1 WHERE u.id=@user_11 AND NOT EXISTS(SELECT 1 FROM `order` WHERE order_no='DEMO_V2_REVIEW_01_1');
INSERT INTO comment (user_id,scenic_id,score,content,reply,status,create_time) SELECT o.user_id,o.scenic_id,3,'【演示评价】杭州西湖的沿湖步道让人印象深刻。整体中规中矩，建议预留更充裕的时间，先看路线再出发。',NULL,1,DATE_ADD(o.visit_date,INTERVAL 1 DAY) FROM `order` o WHERE o.order_no='DEMO_V2_REVIEW_01_1' AND NOT EXISTS(SELECT 1 FROM comment c WHERE c.user_id=o.user_id AND c.scenic_id=o.scenic_id);
